export const MEDIUM_BY_ID = Object.fromEntries(MEDIUMS.map((m) => [m.id, m]));

const clean = (s, max = 600) => String(s ?? '').replace(/\s+/g, ' ').trim().slice(0, max);

/** Normalise and validate a brand brief coming from the client. */
export function normaliseBrief(raw = {}) {
  const brief = {
    brandName: clean(raw.brandName, 80),
    productName: clean(raw.productName, 120),
    description: clean(raw.description, 1500),
    tagline: clean(raw.tagline, 140),
    colors: Array.isArray(raw.colors)
      ? raw.colors.filter((c) => /^#[0-9a-f]{6}$/i.test(c)).slice(0, 4)
      : [],
    style: clean(raw.style, 200),
  };
  const missing = !brief.brandName ? 'Please give your brand a name.' : !brief.description ? 'Please describe your product.' : null;
  if (missing) throw Object.assign(new Error(missing), { status: 400 });
  return brief;
}

function brandBlock(brief) {
  const lines = [
    `Brand name: "${brief.brandName}"`,
    brief.productName && `Product: ${brief.productName}`,
    `Product description: ${brief.description}`,
    brief.tagline && `Tagline (render verbatim when text appears): "${brief.tagline}"`,
    brief.colors.length && `Brand colour palette: ${brief.colors.join(', ')}`,
    brief.style && `Overall art direction / mood: ${brief.style}`,
  ];
  return lines.filter(Boolean).join('\n');
}

/** Prompt for the canonical product reference shot. */
export function referencePrompt(brief) {
  return [
    'Create the definitive hero product packshot for a new product launch. This image will be reused as the master reference for an entire ad campaign, ',
    'so the product design must be specific, distinctive and fully visible.',
    '',
    brandBlock(brief),
    '',
    'Requirements:',
    '- A single product, centred, shown in a three-quarter view, entirely in frame with nothing cropped.',
    `- The product's own packaging/label clearly shows the brand name "${brief.brandName}" in a distinctive logo wordmark.`,
    '- Seamless neutral light-grey studio background, soft even lighting, gentle contact shadow.',
    '- Photorealistic commercial product photography, sharp focus, high detail on materials and label.',
    '- No other objects, no props, no additional text besides what is printed on the product itself.',
    `- ${NO_PEOPLE_RULE}`,
  ].join('\n');
}

/** Prompt for placing the reference product into a given medium. */
export function mediumPrompt(brief, medium, { variationNote } = {}) {
  return [
    `Using the attached image as the exact product reference, create a ${medium.label.toLowerCase()} advertisement for this product.`,
    '',
    'PRODUCT LOCK — consistency is the top priority:',
    '- The product must be the IDENTICAL object from the reference image: same shape, proportions, materials, colours, cap/lid/details, label layout and logo.',
    `- Reproduce the logo wordmark "${brief.brandName}" on the product exactly as it appears in the reference. Do not redesign, restyle or recolour the product.`,
    '- Only the camera angle, lighting and surroundings may change to fit the scene.',
    '',
    brandBlock(brief),
    '',
    `Scene: ${medium.scene}`,
    '',
    'Typography: any advertising copy must be spelled exactly as given above, crisp and legible. Do not invent extra slogans, prices, URLs or fake words.',
    variationNote ? `Variation request: ${clean(variationNote, 300)}` : '',
    '',
    NO_PEOPLE_RULE,
  ]
    .filter((l) => l !== '')
    .join('\n');
}

/** Prompt for the vision model that checks for people. */
export const PEOPLE_CHECK_PROMPT =
  'Look carefully at this image. Does it contain any human being or any part of one — a person, face, hand, finger, arm, body, silhouette, ' +
  "human shadow or reflection, mannequin, or an illustrated/cartoon person (including people shown inside posters or screens within the image)? " +
  'Reply with exactly one word: YES or NO.';
